@app.cell
def _(mo):
    import csv as _csv
    import re as _re
    from pathlib import Path as _Path

    # Produce bom.csv next to this notebook with:
    #   kicad-cli sch export bom --fields "*" --ref-range-delimiter "" -o bom.csv <sheet>.kicad_sch
    bom_path = _Path("bom.csv")
    bom_rows = []
    if bom_path.exists():
        with bom_path.open(newline="", encoding="utf-8-sig") as _fh:
            bom_rows = list(_csv.DictReader(_fh))

    _SI = {"p": 1e-12, "n": 1e-9, "u": 1e-6, "µ": 1e-6, "m": 1e-3, "k": 1e3, "K": 1e3, "M": 1e6, "G": 1e9, "R": 1.0, "r": 1.0}

    def parse_value(text):
        """'22.1k' -> 22100.0, '4k7' -> 4700.0, '100nF' -> 1e-07, '27R' -> 27.0; None if not numeric."""
        t = str(text).strip().replace("Ω", "").replace("ohm", "").replace(" ", "")
        m = _re.match(r"^(\d+)([pnuµmkKMGRr])(\d+)", t)
        if m:
            return float(m.group(1) + "." + m.group(3)) * _SI[m.group(2)]
        m = _re.match(r"^([0-9]*\.?[0-9]+(?:[eE][-+]?\d+)?)([pnuµmkKMGRr]?)", t)
        if not m:
            return None
        return float(m.group(1)) * _SI.get(m.group(2), 1.0)

    def _refs(cell):
        out = []
        for part in _re.split(r"[,\s]+", cell or ""):
            m = _re.match(r"^([A-Za-z]+)(\d+)-[A-Za-z]*(\d+)$", part)
            if m:
                out += [m.group(1) + str(n) for n in range(int(m.group(2)), int(m.group(3)) + 1)]
            elif part:
                out.append(part)
        return out

    bom_by_ref = {}
    for _row in bom_rows:
        _refcol = _row.get("Reference") or _row.get("Refs") or _row.get("Ref") or ""
        for _r in _refs(_refcol):
            bom_by_ref[_r] = _row

    mo.vstack([
        mo.md(f"**BOM:** {len(bom_rows)} rows loaded from `{bom_path}`" if bom_rows else
              "**BOM:** `bom.csv` not found — export it with kicad-cli (see comment in this cell)."),
        mo.ui.table(bom_rows) if bom_rows else mo.md(""),
    ])
    return (bom_by_ref, bom_path, bom_rows, parse_value)


@app.cell
def _(bom_by_ref, mo, parse_value, res_power_ui, rst_pullup_ui, vbus_div_ui):
    _links = [
        ("R201", "vbus_div", "R1", 1000, "kΩ", vbus_div_ui),
        ("R202", "vbus_div", "R2", 1000, "kΩ", vbus_div_ui),
        ("R203", "rst_pullup", "R", 1, "Ω", rst_pullup_ui),
        ("R203", "res_power", "R", 1, "Ω", res_power_ui),
    ]
    _lines = ["| Refdes | Calculator input | Calculator value | Schematic value | Match |", "|---|---|---|---|---|"]
    for _ref, _calc, _inp, _scale, _unit, _ui in _links:
        _calc_v = float(_ui.value[_inp]) * _scale
        _row = bom_by_ref.get(_ref)
        _sch = parse_value(_row.get("Value", "")) if _row else None
        if _sch is None:
            _ok = "no BOM data"
        else:
            _ok = "OK" if abs(_sch - _calc_v) <= 1e-3 * max(abs(_sch), 1e-30) else "MISMATCH"
        _shown = _row.get("Value", "") if _row else "—"
        _lines.append(f"| {_ref} | {_calc}.{_inp} | {_ui.value[_inp]} {_unit} | {_shown} | {_ok} |")
    mo.md("**Calculator inputs vs schematic values**\n\n" + "\n".join(_lines))
    return


