@app.cell
def _(mo):
    vbus_div_src = r'''def calc(VBUS, R1, R2, VIH, Vpin_max):
    # VBUS sense divider: R1 (R201) from VBUS to the VBUS pin, R2 (R202) pin to GND.
    # R1, R2 are entered in kOhm -> convert to Ohm.
    r1 = R1 * 1e3
    r2 = R2 * 1e3
    Vpin = VBUS * r2 / (r1 + r2)          # unloaded divider (pin leakage neglected)
    I_div = VBUS / (r1 + r2)              # A
    return {
        "Vpin": Vpin,
        "m_VIH": Vpin - VIH,              # > 0  -> VBUS presence detected
        "m_max": Vpin_max - Vpin,         # > 0  -> pin inside its rating
        "I_div": I_div * 1e6,             # uA
    }
'''
    vbus_div_ui = mo.ui.dictionary({
        "VBUS": mo.ui.slider(4, 5.5, step=0.01, value=5, label="V_BUS [V]", show_value=True, include_input=True),
        "R1": mo.ui.slider(1, 100, step=0.1, value=22.1, label="R1 (R201, top) [kΩ]", show_value=True, include_input=True),
        "R2": mo.ui.slider(1, 100, step=0.1, value=47.5, label="R2 (R202, bottom) [kΩ]", show_value=True, include_input=True),
        "VIH": mo.ui.slider(0.5, 3.6, step=0.01, value=2.31, label="V_IH(min) VBUS pin [V]", show_value=True, include_input=True),
        "Vpin_max": mo.ui.slider(1, 6, step=0.01, value=3.6, label="V_pin(max) rating [V]", show_value=True, include_input=True),
    })
    vbus_div_wc = mo.ui.switch(label="Worst-case (EVA corners)")
    mo.vstack([mo.md(r"""
### 5.1 VBUS sense divider (R201 / R202)

$$
V_{pin} = V_{BUS}\,\frac{R_2}{R_1+R_2}
$$

*Source: CP2102N data sheet — VBUS sense / bus-powered connection figure (enter Doc ID, rev, page)*  
Analysis: A2, A8
"""), vbus_div_ui, vbus_div_wc])
    return (vbus_div_src, vbus_div_ui, vbus_div_wc)


@app.cell
def _(mo, vbus_div_src, vbus_div_ui, vbus_div_wc):
    _ns = {}
    exec(vbus_div_src, _ns)
    _kw = dict(vbus_div_ui.value)
    _r = _ns["calc"](**_kw)
    _meta = [
        ("Vpin", "V_pin", "V", ".3f", {}),
        ("m_VIH", "Margin to V_IH", "V", ".3f", {"min": 0, "warn_min": 0.2}),
        ("m_max", "Margin to V_pin(max)", "V", ".3f", {"min": 0, "warn_min": 0.1}),
        ("I_div", "Divider current", "µA", ".1f", {}),
    ]
    _tol = {"VBUS": 5, "R1": 1, "R2": 1}
    _lo, _hi = {}, {}
    if vbus_div_wc.value:
        import itertools as _it
        for _signs in _it.product((-1.0, 1.0), repeat=len(_tol)):
            _k2 = dict(_kw)
            for (_n, _p), _sg in zip(_tol.items(), _signs):
                _k2[_n] = _kw[_n] * (1 + _sg * _p / 100.0)
            for _k, _x in _ns["calc"](**_k2).items():
                _lo[_k] = min(_lo.get(_k, _x), _x)
                _hi[_k] = max(_hi.get(_k, _x), _x)
    _rows = []
    for _k, _lbl, _u, _f, _lim in _meta:
        _v = float(_r[_k])
        _st = ""
        if _lim:
            _st = "PASS"
            if ("warn_min" in _lim and _v < _lim["warn_min"]) or ("warn_max" in _lim and _v > _lim["warn_max"]):
                _st = "WARN"
            if ("min" in _lim and _v < _lim["min"]) or ("max" in _lim and _v > _lim["max"]):
                _st = "FAIL"
        _wc = f" ({_lo[_k]:{_f}} … {_hi[_k]:{_f}})" if _k in _lo else ""
        _rows.append(f"| {_lbl} | `{_v:{_f}}`{_wc} | {_u} | {_st} |")
    mo.vstack([
        mo.md("| Output | Value (EVA min … max) | Unit | Check |\n|---|---|---|---|\n" + "\n".join(_rows)),
        mo.accordion({"Show Python": mo.ui.code_editor(value=vbus_div_src, language="python", disabled=True)}),
    ])
    return


@app.cell
def _(mo):
    ldo_diss_src = r'''def calc(Vin, Vout, I_load, I_q, I_budget):
    # Currents entered in mA.
    il = I_load * 1e-3
    iq = I_q * 1e-3
    P_pkg = (Vin - Vout) * il + iq * Vin       # whole package (LDO + core)
    P_ldo = (Vin - Vout) * (il + iq)            # pass element only
    I_vbus = I_load + I_q                       # mA drawn from VBUS
    return {
        "P_pkg": P_pkg * 1e3,
        "P_ldo": P_ldo * 1e3,
        "I_vbus": I_vbus,
        "headroom": I_budget - I_vbus,
    }
'''
    ldo_diss_ui = mo.ui.dictionary({
        "Vin": mo.ui.slider(3, 5.5, step=0.01, value=5.25, label="V_IN (VREGIN = VBUS) [V]", show_value=True, include_input=True),
        "Vout": mo.ui.slider(1.8, 3.6, step=0.01, value=3.3, label="V_OUT (VDD/VIO) [V]", show_value=True, include_input=True),
        "I_load": mo.ui.slider(0, 100, step=0.5, value=10, label="I_LOAD external [mA]", show_value=True, include_input=True),
        "I_q": mo.ui.slider(0, 30, step=0.1, value=9.5, label="I_Q (device supply) [mA]", show_value=True, include_input=True),
        "I_budget": mo.ui.slider(1, 900, step=1, value=100, label="VBUS budget [mA]", show_value=True, include_input=True),
    })
    mo.vstack([mo.md(r"""
### 5.2 Internal LDO dissipation & VBUS budget

$$
P_{pkg} = (V_{IN}-V_{OUT})\,I_{LOAD} + I_Q\,V_{IN}
$$

*Source: CP2102N data sheet — regulator & supply-current tables (enter Doc ID, rev, page)*  
Analysis: A4
"""), ldo_diss_ui])
    return (ldo_diss_src, ldo_diss_ui)


@app.cell
def _(ldo_diss_src, ldo_diss_ui, mo):
    _ns = {}
    exec(ldo_diss_src, _ns)
