@app.cell
def _(mo):
    rc_filter_src = r'''import math

def calc(R, C, f):
    c = C * 1e-9
    fc = 1.0 / (2 * math.pi * R * c)
    att = -10.0 * math.log10(1.0 + (f * 1e6 / fc) ** 2)
    return {"fc": fc / 1e3, "tau": R * c * 1e6, "att": att}
'''
    rc_filter_ui = mo.ui.dictionary({
        "R": mo.ui.slider(1, 1000000, step=1, value=100, label="R [Ω]", show_value=True, include_input=True),
        "C": mo.ui.slider(0.001, 10000, step=0.001, value=10, label="C [nF]", show_value=True, include_input=True),
        "f": mo.ui.slider(0.001, 3000, step=0.001, value=30, label="Noise frequency [MHz]", show_value=True, include_input=True),
    })
    rc_filter_wc = mo.ui.switch(label="Worst-case (EVA corners)")
    mo.vstack([mo.md(r"""
### A13 RC low-pass filter cutoff & attenuation

$$
f_c = \frac{1}{2\pi R C} \qquad A(f) = -10\log_{10}\!\left(1+(f/f_c)^2\right)\ \text{dB}
$$

*Source: First-order RC*  
Analysis: A13
"""), rc_filter_ui, rc_filter_wc])
    return (rc_filter_src, rc_filter_ui, rc_filter_wc)


@app.cell
def _(mo, rc_filter_src, rc_filter_ui, rc_filter_wc):
    _ns = {}
    exec(rc_filter_src, _ns)
    _kw = dict(rc_filter_ui.value)
    _r = _ns["calc"](**_kw)
    _meta = [
        ("fc", "f_c", "kHz", ".2f", {}),
        ("tau", "τ = RC", "µs", ".3f", {}),
        ("att", "Attenuation at f", "dB", ".1f", {}),
    ]
    _tol = {"R": 1, "C": 10}
    _lo, _hi = {}, {}
    if rc_filter_wc.value:
        import itertools as _it
        for _signs in _it.product((-1.0, 1.0), repeat=len(_tol)):
            _k2 = dict(_kw)
            for (_n, _p), _sg in zip(_tol.items(), _signs):
                _k2[_n] = _kw[_n] * (1 + _sg * _p / 100.0)
            for _k, _x in _ns["calc"](**_k2).items():
                _lo[_k] = min(_lo.get(_k, _x), _x)
                _hi[_k] = max(_hi.get(_k, _x), _x)
    _rows = []
    for _k, _lbl, _u, _f, _lim in _meta:
        _v = float(_r[_k])
        _st = ""
        if _lim:
            _st = "PASS"
            if ("warn_min" in _lim and _v < _lim["warn_min"]) or ("warn_max" in _lim and _v > _lim["warn_max"]):
                _st = "WARN"
            if ("min" in _lim and _v < _lim["min"]) or ("max" in _lim and _v > _lim["max"]):
                _st = "FAIL"
        _wc = f" ({_lo[_k]:{_f}} … {_hi[_k]:{_f}})" if _k in _lo else ""
        _rows.append(f"| {_lbl} | `{_v:{_f}}`{_wc} | {_u} | {_st} |")
    mo.vstack([
        mo.md("| Output | Value (EVA min … max) | Unit | Check |\n|---|---|---|---|\n" + "\n".join(_rows)),
        mo.accordion({"Show Python": mo.ui.code_editor(value=rc_filter_src, language="python", disabled=True)}),
    ])
    return


